def cmd_call(args):
    ws = _workspace(args)
    state_path = _seed_if_needed(ws)
    now = args.now or DEFAULT_NOW
    try:
        params = json.loads(args.args) if args.args else {}
    except json.JSONDecodeError as e:
        _emit({"error": f"--args must be valid JSON: {e}"}, 1)
    if not isinstance(params, dict):
        _emit({"error": "--args must be a JSON object"}, 1)

    env_data = ENV_DATA_CLASS.load(state_path)
    env = ENV_CLASS(env_data, now=now)

    session_path = ws / "session.json"
    if session_path.exists():
        for k, v in _dec(json.loads(session_path.read_text())).items():
            setattr(env, k, v)

    handler = env.tool_handlers.get(args.tool)
    if handler is None:
        _emit({"error": f"Unknown tool '{args.tool}'. Run `tools` to list available tools."}, 1)

    try:
        result = handler(params)
    except Exception as e:  # domain handlers raise on bad input; surface as JSON
        _emit({"error": f"{type(e).__name__}: {e}"}, 1)

    # Persist mutated DB (rebuild EnvironmentData from live indexes so created rows are captured).
    rebuilt = ENV_DATA_CLASS(**{field: list(getattr(env, attr).values()) for field, attr in SAVE_MAP.items()})
    rebuilt.save(state_path)

    logger.info(
        "Saved shopping env to world.db: %s products, %s customers, %s carts, %s cart_items",
        len(self.products), len(self.customers), len(self.carts), len(self.cart_items),
    )

@classmethod
def load(cls, path: Path | None = None) -> SAEnvironmentData:
    """Build the scoped shopping environment from the unified world.db.

    `path` is accepted for CLI back-compat but ignored.
    """
    conn = _connect()
    try:
        user_ids = _scoped_user_ids(conn)
        uq = ",".join("?" * len(user_ids)) if user_ids else "''"
        products = [
            Product.from_dict(_row_to_product(r))
            for r in conn.execute("SELECT * FROM products WHERE source_skill=?", (SOURCE_SKILL,))
        ]
        customers = [
            Customer.from_dict(_row_to_customer(r))
            for r in conn.execute(f"SELECT * FROM users WHERE user_id IN ({uq})", user_ids)
        ]
        carts = [
            Cart.from_dict(_row_to_cart(r))
            for r in conn.execute(f"SELECT * FROM carts WHERE customer_id IN ({uq})", user_ids)
        ]
        cart_items = [
            CartItem.from_dict(_row_to_cart_item(r))
            for r in conn.execute(f"SELECT * FROM cart_items WHERE customer_id IN ({uq})", user_ids)
        ]
        promotions = [
            Promotion.from_dict(_row_to_promotion(r))
            for r in conn.execute("SELECT * FROM promotions")
        ]
    finally:
        conn.close()
    return cls(
        products=products,
        customers=customers,
        carts=carts,

